"""Retry policy for outbound HTTP calls made through shipclient."""

import re
from datetime import datetime, timezone

_RETRYABLE_STATUSES = {429, 502, 503, 504}
_IDEMPOTENT_METHODS = {"GET", "HEAD", "OPTIONS", "PUT", "DELETE"}

# (attempts, backoff cap, longest accepted Retry-After) per current profile.
_DEFAULT_PROFILE = (5, 8.0, 30.0)
_PROFILES = {
    "catalog": (6, 8.0, 30.0),
    "ledger": (8, 3.0, 60.0),
    "auth": (6, 6.0, 20.0),
    "payments": (3, 1.0, 30.0),
    "ledger-export": (4, 8.0, 10.0),
    "reports": (9, 5.0, 120.0),
    "inventory": (7, 4.0, 90.0),
    "search": (10, 12.0, 45.0),
    "shipping": (8, 3.0, 40.0),
    "media": (5, 8.0, 15.0),
}

_MONTHS = {
    m: i + 1
    for i, m in enumerate(
        ["Jan", "Feb", "Mar", "Apr", "May", "Jun",
         "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]
    )
}
_DAYS = {"Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"}
_HTTP_DATE = re.compile(
    r"([A-Za-z]{3}), (\d{2}) ([A-Za-z]{3}) (\d{4}) (\d{2}):(\d{2}):(\d{2}) GMT"
)


def _header(headers: dict[str, str] | None, name: str) -> str | None:
    for key, value in (headers or {}).items():
        if key.lower() == name:
            return value
    return None


def _retry_after(value: str | None, now: datetime) -> float | None:
    """Wait in seconds from a Retry-After value, or None if absent/malformed."""
    if value is None:
        return None
    value = value.strip()
    if re.fullmatch(r"[0-9]+", value):
        return float(int(value))
    m = _HTTP_DATE.fullmatch(value)
    if not m or m[1] not in _DAYS or m[3] not in _MONTHS:
        return None
    try:
        when = datetime(
            int(m[4]), _MONTHS[m[3]], int(m[2]),
            int(m[5]), int(m[6]), int(m[7]), tzinfo=timezone.utc,
        )
    except ValueError:
        return None
    return max(0.0, (when - now).total_seconds())


def retry_delay(
    method: str,
    request_headers: dict[str, str],
    attempt: int,
    status: int | None,
    response_headers: dict[str, str],
    now: datetime,
) -> float | None:
    """Seconds to wait before the next attempt, or None to give up.

    `attempt` is the number of the attempt that just failed, 1 for the first.
    `status` is None when there was no response (a connection error).
    `now` is the current time, timezone-aware UTC.
    """
    if status is not None and status not in _RETRYABLE_STATUSES:
        return None

    if method.upper() not in _IDEMPOTENT_METHODS:
        key = _header(request_headers, "idempotency-key")
        if key is None or not key.strip():
            return None

    service = (_header(request_headers, "x-service") or "").strip().lower()
    max_attempts, cap, max_retry_after = _PROFILES.get(service, _DEFAULT_PROFILE)

    if attempt >= max_attempts:
        return None

    delay = min(0.25 * 2 ** (attempt - 1), cap)

    if status in (429, 503):
        wait = _retry_after(_header(response_headers, "retry-after"), now)
        if wait is not None:
            if wait > max_retry_after:
                return None
            delay = max(delay, wait)
    return delay
EOF
